CREATE TRIGGER `runtime_guardprobe_insert_guard` BEFORE INSERT ON `runtime_guardprobe` FOR EACH ROW BEGIN DECLARE actual_signature CHAR(64);
        SELECT SHA2(GROUP_CONCAT(CONCAT(TRIGGER_NAME,':',SHA2(ACTION_STATEMENT,256)) ORDER BY BINARY TRIGGER_NAME SEPARATOR '|'),256)
        INTO actual_signature FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME<>'runtime_guardprobe_insert_guard';
        IF NOT (actual_signature <=> 'e4fd0bda192fdce64f25ffdd1602a765bd0dd91070fff03e089ac5cfb8f8bdd9') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='bazar_guard_contract_changed'; END IF;
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='bazar_guard_contract_ready'; END
